package com.kaipai.service.ai.impl;
import com.fasterxml.jackson.databind.ObjectMapper; import com.kaipai.common.exception.BizException; import com.kaipai.model.ai.entity.AiProfileImportConfig; import com.kaipai.service.ai.ProfileImportConnectionTester; import java.net.URI; import java.net.http.*; import java.time.Duration; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor public class ProfileImportConnectionTesterImpl implements ProfileImportConnectionTester { private final ObjectMapper mapper; public void test(AiProfileImportConfig config,String apiKey){try{String body=mapper.writeValueAsString(Map.of("model",config.getModelName(),"messages",List.of(Map.of("role","user","content","health check")),"max_tokens",1));HttpRequest request=HttpRequest.newBuilder(URI.create(config.getEndpoint())).timeout(Duration.ofMillis(config.getReadTimeoutMs())).header("Authorization","Bearer "+apiKey).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build();HttpResponse<Void> response=HttpClient.newBuilder().connectTimeout(Duration.ofMillis(config.getConnectTimeoutMs())).build().send(request,HttpResponse.BodyHandlers.discarding());if(response.statusCode()<200||response.statusCode()>=300)throw new BizException("DeepSeek 连接测试失败");}catch(BizException e){throw e;}catch(Exception e){throw new BizException("DeepSeek 连接测试失败");}} }

